let integration={loading:true,offline:false,connections:{},calendar:{status:'disconnected'},mail:{status:'disconnected'},dida:{status:'disconnected'}};
let csrf='',refreshBusy=false,nextMailBusy=false,connectionTimer;
const remoteTime=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'尚未同步';
const remoteLink=(url,label)=>safeURL(url)?`<a class="text-btn" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'';
function syncStatus(resource){if(integration.loading)return '<span class="muted">正在读取…</span>';if(integration.offline)return '<span class="muted">需要启动本机同步服务</span>';return `<span class="muted">${resource.updatedAt?'更新于 '+remoteTime(resource.updatedAt):'尚未连接'}${resource.status==='error'?' · 同步失败':''}</span>`}
function remoteEmpty(resource,emptyText){if(resource.status==='error')return `<div class="connection-empty error-banner">${esc(resource.error)}${resource.data?'<br>以下为上次成功读取的内容。':''}</div>`;if(resource.status==='disconnected')return `<div class="connection-empty"><h3>连接后，在这里查看</h3><p>通过只读授权读取你的账户内容。</p><button class="secondary" data-page="me">前往连接账户</button></div>`;return empty(emptyText)}
function calendarContent(day){const r=integration.calendar;if(!r.data)return remoteEmpty(r,'这一天没有日程。');const list=r.data.events.filter(e=>e.days.includes(day));const current=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date());if(r.data.today!==current)return '<div class="error-banner">日历日期已变化，正在等待重新同步。上次内容不会当作今天的日程显示。</div>';return (r.status==='error'?remoteEmpty(r,''):'')+(list.length?list.map(e=>{const time=e.allDay?'全天':new Date(e.start).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'});const end=e.allDay?'':new Date(e.end).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'});return `<article class="calendar-event"><div class="event-time">${time}${end?`<small>${end}</small>`:''}</div><div class="event-detail"><h3>${esc(e.title)}</h3><p>${esc(e.calendar)}${e.location?' · '+esc(e.location):''}</p>${remoteLink(e.url,'查看日程')}</div></article>`}).join(''):empty('这一天没有日程。'))}
function calendarPanel(compact=false){const r=integration.calendar;const dates=r.data||{};return `<section class="card"><div class="section-head"><h2>Google 日历</h2>${syncStatus(r)}</div><p class="service-caption">今天与明天 · 上海时间</p>${r.data?.warnings?.length?`<p class="error-banner">${esc(r.data.warnings.join('；'))}</p>`:''}<div class="day-sections"><section><h3 class="day-heading">今天 <small>${esc(dates.today||'')}</small></h3>${calendarContent(dates.today)}</section><section><h3 class="day-heading">明天 <small>${esc(dates.tomorrow||'')}</small></h3>${calendarContent(dates.tomorrow)}</section></div></section>`}
function didaPanel(){const r=integration.dida;return `<section class="card"><div class="section-head"><h2>滴答清单 · 置顶内容</h2>${syncStatus(r)}</div><div class="connection-empty"><h3>置顶同步暂不可用</h3><p>官方接口未提供置顶标记，不能可靠读取“已置顶”列表。</p>${remoteLink('https://dida365.com/webapp/','打开滴答清单')}</div></section>`}
function mailList(compact=false){const r=integration.mail;if(!r.data)return remoteEmpty(r,'没有未读邮件。');const messages=compact?r.data.messages.slice(0,4):r.data.messages;return (r.status==='error'?remoteEmpty(r,''):'')+(messages.length?messages.map(m=>`<article class="mail-item"><div class="mail-avatar">${esc(m.from.replace(/["<]/g,'').slice(0,1)||'邮')}</div><div class="mail-detail"><div class="row"><strong>${esc(m.from)}</strong><time>${remoteTime(m.date)}</time></div><h3>${esc(m.title)}</h3>${!compact?`<p>${esc(m.snippet)}</p>`:''}${remoteLink(m.url,'在 Gmail 中打开')}</div></article>`).join(''):empty('没有未读邮件，收件箱已查看完毕。'))}
function mailPage(){const r=integration.mail;return `<div class="welcome row"><div><span class="eyebrow">YOUR UNREAD MAIL</span><h1>我的邮件</h1><p class="muted">集中查看 Gmail 中尚未阅读的邮件。</p></div><button class="primary" data-refresh ${refreshBusy?'disabled':''}>${refreshBusy?'刷新中…':'刷新邮件'}</button></div><section class="card"><div class="section-head"><h2>未读邮件 ${r.data?`<span class="pill">已显示 ${r.data.messages.length} 封</span>`:''}</h2>${syncStatus(r)}</div><p class="service-caption">每分钟自动刷新 · 不含垃圾邮件和垃圾箱 · 查看列表不会标为已读</p>${mailList()}${r.data?.nextPageToken?`<button class="secondary" id="more-mail" ${nextMailBusy?'disabled':''}>${nextMailBusy?'读取中…':'加载更多未读邮件'}</button>`:''}</section>`}
function schedulePage(){return `<div class="welcome row"><div><span class="eyebrow">YOUR DAYS, TOGETHER</span><h1>我的日程</h1><p class="muted">Google 日历与滴答清单，在一处查看。</p></div><button class="primary" data-refresh ${refreshBusy?'disabled':''}>${refreshBusy?'刷新中…':'刷新日程'}</button></div><div class="columns"><div class="stack">${calendarPanel()}<details class="card"><summary>本地安排（保留原有记录）</summary><div class="section-head" style="margin-top:20px"><h2>我的本地安排</h2><button class="text-btn" data-add="task">＋ 添加安排</button></div>${week()}${taskList(byDay())}</details></div><div class="stack">${didaPanel()}</div></div>`}
function connectionSettings(){const c=integration.connections;return `<section class="card settings connection-settings"><div class="section-head"><h2>账户连接</h2><span class="pill">只读访问</span></div><p class="service-caption">账户授权仅用于此电脑。同步内容不会写入源码或浏览器备份。</p>${integration.offline?'<p class="error-banner">当前是静态预览。请用项目中的启动方式运行本机服务后连接账户。</p>':''}${['google','dida'].map(p=>{const item=c[p]||{},name=p==='google'?'Google 日历与 Gmail':'滴答清单';return `<div class="provider-setting"><div class="row"><div><h3>${name}</h3><p class="muted">${item.connected?'已连接':item.configured?'已配置，等待授权':'尚未配置应用授权'}</p></div><span class="tag">${p==='google'?'日历和邮件只读':'任务只读'}</span></div>${p==='dida'?'<p class="service-caption">官方接口目前不提供置顶标记。连接账户也不能自动识别置顶。</p>':''}<div class="provider-actions"><button class="primary" data-connect="${p}" ${!item.configured||integration.offline?'disabled':''}>${item.connected?'重新授权':'连接账户'}</button>${item.connected?`<button class="secondary" data-disconnect="${p}">移除本机连接</button>`:''}</div><details ${!item.configured?'open':''}><summary>${item.configured?'更换应用配置':'配置应用授权'}</summary><p class="service-caption">${p==='google'?`在 ${remoteLink('https://console.cloud.google.com/apis/credentials','Google Cloud')} 创建“Web 应用”OAuth 客户端，并启用 Gmail API、Google Calendar API。测试模式下将自己的邮箱加入测试用户。`:`在 ${remoteLink('https://developer.dida365.com/manage','滴答清单开发者中心')} 注册应用。`}</p><p class="service-caption">授权回调地址</p><code class="callback-uri">${esc(item.redirectUri||`http://127.0.0.1:8765/auth/${p}/callback`)}</code><form data-config="${p}" autocomplete="off"><label class="field">应用 ID（Client ID）<input name="clientId" required maxlength="1000" autocomplete="off"></label><label class="field">应用密钥（Client Secret）<input type="password" name="clientSecret" required maxlength="1000" autocomplete="new-password"></label><button class="secondary" ${integration.offline?'disabled':''}>保存到此电脑</button><p class="form-feedback" role="status"></p></form></details></div>`}).join('')}</section>`}
async function api(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(120000)});const data=await response.json();if(!response.ok)throw Error(data.error||'读取失败，请重试');return data}
async function refreshConnections(showToast=false){if(refreshBusy)return;refreshBusy=true;try{if(!csrf){const session=await api('/api/session');csrf=session.csrf;integration.connections=session.connections}const value=await api('/api/dashboard');integration={...value,loading:false,offline:false};if(showToast)toast('已读取账户同步状态')}catch(e){integration.loading=false;integration.offline=!csrf;for(const p of ['calendar','mail','dida'])integration[p]={...integration[p],status:'error',error:e.message};if(showToast)toast(e.message)}finally{refreshBusy=false;if(!document.getElementById('editor').open)render()}}
function bindConnections(){document.querySelectorAll('[data-refresh]').forEach(b=>b.onclick=()=>refreshConnections(true));document.querySelectorAll('[data-config]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const feedback=form.querySelector('.form-feedback'),button=form.querySelector('button');button.disabled=true;try{const data=await api('/api/config/'+form.dataset.config,Object.fromEntries(new FormData(form)));integration.connections=data.connections;form.reset();toast('已保存，请点击连接账户完成授权');render()}catch(err){feedback.textContent=err.message;button.disabled=false}});document.querySelectorAll('[data-connect]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const data=await api('/api/connect/'+b.dataset.connect,{});window.location.assign(data.url)}catch(e){toast(e.message);b.disabled=false}});document.querySelectorAll('[data-disconnect]').forEach(b=>b.onclick=()=>confirmAction('移除本机连接？','将删除此电脑保存的访问凭据。不会删除账户中的邮件或日程；如需撤销服务端授权，请到对应账户安全设置操作。',async()=>{try{await api('/api/disconnect/'+b.dataset.disconnect,{});await refreshConnections();toast('已移除本机连接')}catch(e){toast(e.message)}}));const more=document.getElementById('more-mail');if(more)more.onclick=async()=>{nextMailBusy=true;more.disabled=true;try{const data=await api('/api/mail?pageToken='+encodeURIComponent(integration.mail.data.nextPageToken));const old=integration.mail.data.messages,ids=new Set(old.map(m=>m.id));integration.mail.data.messages=[...old,...data.messages.filter(m=>!ids.has(m.id))];integration.mail.data.nextPageToken=data.nextPageToken}catch(e){toast(e.message)}finally{nextMailBusy=false;render()}};}
function startConnections(){refreshConnections();clearInterval(connectionTimer);connectionTimer=setInterval(()=>{if(!document.hidden&&page!=='me'&&!document.getElementById('editor').open)refreshConnections()},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&page!=='me')refreshConnections()})}
